THEME = ("T08", "Relations, graphes et modèles étendus (ReBAC, Zanzibar)")
SOURCE = "Pang et al., « Zanzibar: Google's Consistent, Global Authorization System », USENIX ATC, 2019 ; Fong, « Relationship-Based Access Control », CODASPY, 2011 ⚠ à vérifier"
Q = [
(1,"Sur quoi ReBAC fonde-t-il les décisions d'accès ?","Sur les relations entre entités (par exemple propriétaire de, membre de)","Sur le mot de passe","Sur la couleur du fichier","Sur la taille du fichier",
 "ReBAC raisonne sur un graphe de relations."),
(1,"Que signifie ReBAC ?","Relationship-Based Access Control","Resource-Based Access Check","Role-Extended Business Access Control","Remote Binary Access Control",
 "Le contrôle d'accès fondé sur les relations a été formalisé dès 2011."),
(2,"Quel système met en œuvre ReBAC à très grande échelle ?","Zanzibar de Google","Un bloc-notes","Un traitement de texte","Un client de messagerie",
 "Zanzibar sert Drive, YouTube et d'autres services de Google (publié en 2019)."),
(2,"Quelle structure de données Zanzibar utilise-t-il pour représenter les droits ?","Des tuples de relation (objet, relation, utilisateur)","Des matrices de bits","Des fichiers texte plats","Des mots de passe chiffrés",
 "Un tuple comme doc:budget#lecteur@alice exprime un droit."),
(2,"Dans la notation doc:budget#editeur@alice, que signifie « editeur » ?","La relation entre l'objet et l'utilisateur","Le nom de l'application","Le mot de passe","La taille du fichier",
 "Alice est éditrice du document « budget »."),
(2,"Quel avantage ReBAC offre-t-il pour le partage de documents ?","Les droits suivent la structure des dossiers, des équipes et des relations","Il supprime les dossiers","Il chiffre les relations","Il interdit le partage",
 "Un lecteur du dossier peut hériter des droits sur les documents contenus."),
(2,"Que veut dire « un membre du groupe Achats est lecteur du dossier Tarifs » ?","Une relation transitive donne des droits à tous les membres du groupe","Seul le groupe peut lire","Aucun droit n'est donné","Le dossier est supprimé",
 "On suit les relations : utilisateur → groupe → dossier."),
(3,"Alice est membre du groupe Achats. Achats est lecteur du dossier Tarifs. Le document Prix est dans Tarifs. Alice peut-elle lire Prix ?","Oui, par héritage via groupe et dossier","Non, seulement Tarifs","Non, car Prix est séparé","Oui, mais seulement en écriture",
 "Les relations sont suivies de proche en proche selon les règles de réécriture de la politique."),
(3,"Que se passe-t-il si Alice quitte le groupe Achats dans ce graphe ?","Elle perd l'accès à Tarifs et à Prix","Elle conserve tous ses droits","Elle devient propriétaire","Le groupe est supprimé",
 "La révocation d'une relation retire tous les droits qui en dépendaient."),
(2,"Quel avantage ReBAC a-t-il sur RBAC pour des ressources très nombreuses et personnalisées ?","Il gère des relations par objet sans multiplier les rôles","Il supprime les objets","Il interdit les utilisateurs","Il n'a pas de politique",
 "Chaque dossier peut avoir ses propres membres sans créer un rôle par dossier."),
(3,"Quel risque présente un graphe de relations très profond ?","Des droits hérités difficiles à comprendre ou à expliquer","Une absence de droits","Un chiffrement trop fort","Un journal trop petit",
 "La lisibilité exige des outils d'explication (« pourquoi Alice a-t-elle ce droit ? »)."),
(3,"Comment appelle-t-on la question « pourquoi cette personne a-t-elle ce droit ? » ?","L'explicabilité de la décision","La rotation des clés","La sauvegarde","La fédération",
 "Elle est indispensable pour auditer et corriger un graphe de relations."),
(2,"Qu'est-ce que le « problème du nouvel ennemi » (new enemy problem) dans Zanzibar ?","Un droit retiré n'est pas appliqué à temps ou une modification antérieure est utilisée","Un virus nouveau","Un nouveau pare-feu","Un nouveau mot de passe",
 "Zanzibar utilise des jetons de cohérence (zookies) pour éviter d'utiliser un état obsolète."),
(3,"Quel danger illustre l'exemple de la suppression d'un accès suivie du dépôt d'un document sensible ?","Le nouvel ennemi pourrait encore voir le document si la révocation n'est pas encore propagée","Le document est chiffré","L'utilisateur est administrateur","Le document est public",
 "L'ordre des événements doit être respecté : d'où la cohérence externe de Zanzibar."),
(2,"Qu'est-ce que l'héritage de permissions par dossier parent ?","Un document hérite des droits du dossier qui le contient","Un dossier hérite d'un document","Le propriétaire hérite du fichier","L'administrateur hérite du rôle",
 "Modèle courant dans Drive : partage d'un dossier partage son contenu."),
(1,"Quel type de service utilise typiquement ReBAC ?","Partage de documents et réseaux sociaux","Calculateur de salaire","Horloge","Traitement de texte local",
 "Les droits suivent la structure sociale et documentaire."),
(2,"Comment un réseau social peut-il appliquer « seuls mes amis voient mes photos » ?","Par une relation « ami de » entre les profils","Par un rôle administrateur","Par un mot de passe partagé","Par un chiffrement local",
 "La règle suit le graphe de relations."),
(2,"Quelle règle ReBAC exprime « amis d'amis » ?","Une relation transitive sur deux sauts","Un rôle","Une classification","Une ACL",
 "ReBAC permet de limiter la profondeur des relations suivies."),
(3,"Pourquoi limite-t-on la profondeur des relations suivies ?","Pour éviter des accès trop larges et des calculs coûteux","Pour supprimer les relations","Pour chiffrer les relations","Pour interdire les groupes",
 "Une profondeur illimitée peut ouvrir des chemins d'accès imprévus."),
(2,"Qu'est-ce que le contrôle d'accès « fondé sur la propriété » dans ReBAC ?","Le propriétaire d'un objet a des droits sur celui-ci par la relation « propriétaire de »","L'administrateur a tous les droits","Le dernier connecté a des droits","Personne n'a de droits",
 "La propriété est une relation parmi d'autres."),
(2,"Quel format de politique ReBAC utilise-t-on dans Zanzibar ?","Un schéma d'espace de noms avec règles de réécriture","Un fichier CSV","Une image","Un tableau de bord",
 "Il définit comment une relation se déduit d'autres relations."),
(3,"Qu'est-ce qu'un « userset » dans Zanzibar ?","Un ensemble d'utilisateurs défini par une relation sur un objet","Un jeu de caractères","Un identifiant de session","Un mot de passe",
 "Par exemple l'ensemble des membres du groupe G : g:G#membre."),
(2,"Quelle problématique la cohérence externe de Zanzibar résout-elle ?","Respecter l'ordre des modifications de droits dans les décisions","L'affichage des pages","Le chiffrement des disques","La compression des journaux",
 "Les décisions doivent refléter les modifications avant le contenu protégé."),
(3,"Comment ReBAC peut-il exprimer « les assistants d'un médecin voient les dossiers de ses patients » ?","Par la chaîne assistant → médecin → patient → dossier","Par un rôle unique","Par une ACL globale","Par un mot de passe",
 "La règle suit les relations de soin."),
(2,"Quel outil open source implémente des idées de Zanzibar ?","SpiceDB ou OpenFGA","Un tableur","Un traitement de texte","Un navigateur",
 "Plusieurs projets reprennent le modèle de tuples de relation."),
(2,"Quelle mesure limite l'accumulation de relations obsolètes ?","Une revue régulière des groupes et un retrait au départ","Aucune","Un chiffrement plus fort","Un nouveau navigateur",
 "Les relations sont des droits : elles doivent être recertifiées."),
(3,"Quelle différence entre RBAC et ReBAC pour un document partagé avec une équipe particulière ?","RBAC nécessiterait un rôle par équipe et par document, ReBAC une relation","Il n'y a aucune différence","ReBAC nécessite plus de rôles","RBAC utilise des graphes",
 "ReBAC réduit la prolifération de rôles pour les ressources nombreuses."),
(2,"Que signifie « Zero Trust » ?","Ne faire confiance à aucun accès par défaut et vérifier chaque requête","Ne faire confiance à personne sauf aux administrateurs","Supprimer les mots de passe","Interdire tout accès",
 "Le principe est « ne jamais faire confiance, toujours vérifier »."),
(2,"Quelle publication du NIST décrit l'architecture Zero Trust ?","SP 800-207","SP 800-162","SP 800-171","SP 800-12",
 "NIST SP 800-207 (2020) définit les concepts et composants d'une architecture Zero Trust."),
(2,"Quel principe de Zero Trust remplace la confiance accordée au réseau interne ?","Vérifier l'identité, l'appareil et le contexte à chaque accès","Faire confiance aux postes internes","Supprimer le pare-feu","Autoriser le VPN pour tous",
 "Le périmètre réseau n'est plus la preuve de légitimité."),
(2,"Quelle idée est associée à Zero Trust dans la hypothèse de travail ?","Supposer la compromission : un attaquant peut déjà être dans le réseau","Supposer qu'il n'y a pas d'attaquant","Supposer que le VPN protège tout","Supposer que les utilisateurs sont sûrs",
 "Cette hypothèse justifie la vérification continue et la segmentation."),
(3,"Quel composant de l'architecture NIST 800-207 décide d'accorder l'accès ?","Le moteur de politique (policy engine)","Le routeur","Le câble","L'imprimante",
 "Le moteur de politique et l'administrateur de politique forment le point de décision."),
(3,"Quel composant NIST 800-207 applique la décision à la session ?","Le point d'application de la politique (PEP)","Le serveur de fichiers","La sauvegarde","Le logiciel de bureautique",
 "Il autorise, surveille et coupe la connexion entre le sujet et la ressource."),
(2,"Qu'est-ce que la micro-segmentation ?","Diviser le réseau en petites zones avec contrôle d'accès entre elles","Fusionner tous les réseaux","Supprimer les VLAN","Chiffrer les câbles",
 "Elle limite les déplacements latéraux d'un attaquant."),
(2,"Que signifie « déplacement latéral » ?","Un attaquant passe d'une machine compromise à d'autres machines","Un utilisateur change de bureau","Un fichier change de nom","Un serveur change d'adresse",
 "La segmentation et le moindre privilège le freinent."),
(2,"Quel score peut remplacer une décision binaire dans un modèle fondé sur le risque ?","Un score de confiance calculé à partir de signaux (appareil, lieu, comportement)","Un score de golf","Un score de qualité d'image","Un score de couleur",
 "Il module les droits ou déclenche une authentification renforcée."),
(3,"Pourquoi un score de risque doit-il être explicable ?","Pour justifier un refus et corriger les faux positifs","Pour supprimer les journaux","Pour cacher la règle","Pour chiffrer le score",
 "Un refus incompréhensible nuit à l'activité et à la confiance dans le dispositif."),
(2,"Qu'est-ce que la « vérification continue » ?","Réévaluer les droits pendant la session et pas seulement à la connexion","Se connecter plusieurs fois par jour","Changer de mot de passe chaque jour","Redémarrer chaque heure",
 "Un changement de contexte peut réduire ou couper l'accès."),
(2,"Quel rôle joue la conformité de l'appareil dans Zero Trust ?","Elle est un critère d'autorisation : appareil à jour, chiffré, géré","Elle est ignorée","Elle remplace l'authentification","Elle supprime le MFA",
 "L'état de santé de l'appareil fait partie du contexte d'accès."),
(3,"Quel risque Zero Trust ne supprime-t-il pas ?","Un utilisateur légitime qui abuse de ses droits","Un pare-feu mal réglé","Les mots de passe volés","Les attaques réseau",
 "Zero Trust réduit l'exposition mais ne remplace pas moindre privilège, journalisation et supervision."),
(2,"Quel mécanisme fournit une identité forte pour un service qui appelle un autre service ?","Un certificat ou jeton de service à durée limitée","Un mot de passe partagé","Un fichier texte","Une adresse IP seule",
 "Les identités de machines et de services doivent aussi être gérées."),
(2,"Que fait un « service mesh » en matière d'accès ?","Authentifie et autorise les échanges entre services, souvent par mTLS","Supprime les services","Chiffre les disques","Compresse les journaux",
 "Il applique des politiques entre microservices."),
(2,"Que signifie mTLS ?","TLS mutuel : les deux parties s'authentifient par certificat","Un TLS miniature","Un TLS multi-mots de passe","Un TLS sans certificat",
 "Le client et le serveur prouvent chacun leur identité."),
(2,"Pourquoi le principe « ne jamais faire confiance » ne supprime-t-il pas le besoin de rôles ?","Les rôles restent un moyen lisible d'exprimer les droits de base","Les rôles sont interdits","Les rôles sont des mots de passe","Les rôles sont des appareils",
 "Zero Trust décrit la façon d'appliquer les décisions, pas le modèle de droits."),
(3,"Quelle limite de la confiance accordée à un VPN traditionnel Zero Trust critique-t-il ?","Une fois connecté, l'utilisateur voit souvent tout le réseau","Le VPN est chiffré","Le VPN est trop lent","Le VPN utilise des mots de passe",
 "L'accès doit être donné application par application, pas au réseau entier."),
(2,"Quel terme désigne l'accès à une application sans exposer le réseau ?","ZTNA (accès réseau Zero Trust)","FTP","SNMP","DHCP",
 "Le ZTNA publie des applications via un courtier d'accès qui applique la politique."),
]
